/* Generated from policy/prohibited-terms.json. Do not edit by hand. */
window.LaborCoinProposalTextPolicy = (() => {
  "use strict";

  const MAX_DESCRIPTION_BYTES = 1000;
  const TOKEN_HASHES = unpackHashes("");
  const PHRASE_HASHES = unpackHashes("");
  const JOINERS = new Set(
    Array.from(".-_*~+/\\|@#$%^&='\"`")
  );

  function unpackHashes(packed) {
    const result = new Set();
    const hex = packed.slice(2);
    for (let offset = 0; offset < hex.length; offset += 64) {
      result.add(`0x${hex.slice(offset, offset + 64)}`);
    }
    return result;
  }

  function canonicalAlphanumeric(character) {
    const code = character.charCodeAt(0);
    if (code >= 65 && code <= 90) {
      return String.fromCharCode(code + 32);
    }
    if (code >= 97 && code <= 122) return character;
    if (code >= 48 && code <= 57) {
      return ({
        "0": "o",
        "1": "i",
        "3": "e",
        "4": "a",
        "5": "s",
        "7": "t",
        "8": "b",
        "9": "g"
      })[character] ?? character;
    }
    return null;
  }

  function normalize(value) {
    let output = "";
    let atBoundary = true;

    for (let index = 0; index < value.length; index += 1) {
      const character = value[index];
      const code = value.charCodeAt(index);

      if (
        code > 0x7e ||
        (code < 0x20 && code !== 0x0a && code !== 0x0d)
      ) {
        return { ok: false, reason: "ascii" };
      }

      if (character === "<" || character === ">") {
        return { ok: false, reason: "markup" };
      }

      const canonical = canonicalAlphanumeric(character);
      if (canonical !== null) {
        output += canonical;
        atBoundary = false;
        continue;
      }

      if (character === " " || character === "\n" || character === "\r") {
        if (!atBoundary && output.length !== 0) {
          output += " ";
          atBoundary = true;
        }
        continue;
      }

      if (JOINERS.has(character)) continue;

      if (!atBoundary && output.length !== 0) {
        output += " ";
        atBoundary = true;
      }
    }

    return { ok: true, normalized: output.trim() };
  }

  function hash(value) {
    return ethers.keccak256(ethers.toUtf8Bytes(value));
  }

  function containsProhibited(normalized) {
    const tokens = normalized.split(" ").filter(Boolean);
    let singletonSequence = "";

    for (let index = 0; index < tokens.length; index += 1) {
      const token = tokens[index];
      if (TOKEN_HASHES.has(hash(token))) return true;

      if (index >= 1) {
        const twoWordPhrase = `${tokens[index - 1]} ${token}`;
        if (PHRASE_HASHES.has(hash(twoWordPhrase))) return true;

        const twoJoined = `${tokens[index - 1]}${token}`;
        if (TOKEN_HASHES.has(hash(twoJoined))) return true;
      }

      if (index >= 2) {
        const threeWordPhrase =
          `${tokens[index - 2]} ${tokens[index - 1]} ${token}`;
        if (PHRASE_HASHES.has(hash(threeWordPhrase))) return true;

        const threeJoined =
          `${tokens[index - 2]}${tokens[index - 1]}${token}`;
        if (TOKEN_HASHES.has(hash(threeJoined))) return true;
      }

      if (token.length === 1) {
        singletonSequence += token;
      } else {
        if (
          singletonSequence.length >= 2 &&
          TOKEN_HASHES.has(hash(singletonSequence))
        ) {
          return true;
        }
        singletonSequence = "";
      }
    }

    return (
      singletonSequence.length >= 2 &&
      TOKEN_HASHES.has(hash(singletonSequence))
    );
  }

  function validate(value) {
    const byteLength = new TextEncoder().encode(value).length;

    if (byteLength === 0) {
      return { allowed: false, reason: "empty", byteLength };
    }
    if (byteLength > MAX_DESCRIPTION_BYTES) {
      return { allowed: false, reason: "length", byteLength };
    }

    const lower = value.toLowerCase();
    if (lower.includes("://") || lower.includes("www.")) {
      return { allowed: false, reason: "url", byteLength };
    }

    const result = normalize(value);
    if (!result.ok) {
      return { allowed: false, reason: result.reason, byteLength };
    }
    if (!result.normalized) {
      return { allowed: false, reason: "words", byteLength };
    }
    if (containsProhibited(result.normalized)) {
      return { allowed: false, reason: "language", byteLength };
    }

    return { allowed: true, reason: "", byteLength };
  }

  function messageFor(result) {
    switch (result.reason) {
      case "empty":
        return "Enter a proposal description.";
      case "length":
        return "Proposal descriptions may not exceed 1,000 bytes.";
      case "ascii":
        return "Use plain English ASCII characters only. Unicode and hidden characters are not accepted.";
      case "markup":
        return "HTML-style markup is not permitted in proposal descriptions.";
      case "url":
        return "Links and URL schemes are not permitted in proposal descriptions.";
      case "words":
        return "The proposal description must contain readable words.";
      case "language":
        return "This proposal contains language prohibited by the permanent proposal-content policy. Revise it before submitting.";
      default:
        return "The proposal description does not satisfy the permanent content policy.";
    }
  }

  return Object.freeze({
    MAX_DESCRIPTION_BYTES,
    validate,
    messageFor
  });
})();
